const reserveCheckedInTournamentParticipants = `-- name: ReserveCheckedInTournamentParticipants :many
INSERT INTO participant_reservations (
    player_id,
    tournament_id,
    revision,
    acquired_at,
    updated_at
)
SELECT participant.player_id,
    roster.tournament_id,
    1,
    $1,
    $1
FROM participants AS participant
JOIN rosters AS roster ON roster.id = participant.roster_id
WHERE participant.roster_id = $2
    AND participant.attendance = 'checked_in'
ORDER BY participant.player_id
ON CONFLICT (player_id) DO UPDATE
SET updated_at = participant_reservations.updated_at
WHERE participant_reservations.tournament_id = EXCLUDED.tournament_id
RETURNING player_id
`

type ReserveCheckedInTournamentParticipantsParams struct {
	AcquiredAt pgtype.Timestamptz
	RosterID   uuid.UUID
}

func (q *Queries) ReserveCheckedInTournamentParticipants(ctx context.Context, arg ReserveCheckedInTournamentParticipantsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, reserveCheckedInTournamentParticipants, arg.AcquiredAt, arg.RosterID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var player_id uuid.UUID
		if err := rows.Scan(&player_id); err != nil {
			return nil, err
		}
		items = append(items, player_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

